class a{static async me(){try{const e=await fetch("/api/auth/me",{credentials:"include"});return e.ok?await e.json():null}catch{return null}}static async createOnlineMatch(e){const t=await fetch("/api/pong/matches",{method:"POST",credentials:"include",headers:{"Content-Type":"application/json"},body:JSON.stringify({playerCount:e.playerCount})});if(!t.ok)throw new Error("Failed to create match");return t.json()}static async joinOnlineMatch(e){const t=await fetch("/api/pong/matches/join",{method:"POST",credentials:"include",headers:{"Content-Type":"application/json"},body:JSON.stringify({code:e.code})});if(!t.ok)throw new Error("Failed to join match");return t.json()}static async postMatchResult(e){await fetch(`/api/pong/matches/${encodeURIComponent(e.matchId)}/result`,{method:"POST",credentials:"include",headers:{"Content-Type":"application/json"},body:JSON.stringify(e)}).catch(()=>{})}static async listOnlinePlayers(){const e=await fetch("/api/pong/players/online",{credentials:"include"});return e.ok?e.json():[]}static async getUserActiveSessions(){const e=await fetch("/api/pong/sessions/active",{credentials:"include"});return e.ok?{activeGames:(await e.json()).activeGames||[]}:{activeGames:[]}}static async checkUserCanJoin(e){try{const t=await this.getUserActiveSessions();return e==="game"&&t.activeGames.length>0?{canJoin:!1,reason:`You are already in an active game (${t.activeGames[0]}). Please finish or exit your current game first.`}:{canJoin:!0}}catch(t){return console.warn("Session check failed:",t),{canJoin:!0}}}static async endSession(e){try{await fetch(`/api/pong/sessions/end/${encodeURIComponent(e)}`,{method:"POST",credentials:"include",headers:{"Content-Type":"application/json"}})}catch(t){console.warn("Failed to end session:",t)}}}export{a as A};
